class Solution {
public:
    long long minOperations(std::vector<int>& nums1, std::vector<int>& nums2, int k) {
        if (k == 0) return nums1 == nums2 ? 0 : -1;
        long long pos = 0, neg = 0;
        for (size_t i = 0; i < nums1.size(); ++i) {
            long long diff = (long long)nums1[i] - nums2[i];
            if (diff % k != 0) return -1;
            if (diff > 0) pos += diff / k;
            else if (diff < 0) neg += (-diff) / k;
        }
        return pos == neg ? pos : -1;
    }
};

class Solution {
    public long minOperations(int[] nums1, int[] nums2, int k) {
        if (k == 0) {
            return java.util.Arrays.equals(nums1, nums2) ? 0 : -1;
        }
        long pos = 0, neg = 0;
        for (int i = 0; i < nums1.length; i++) {
            long diff = (long)nums1[i] - nums2[i];
            if (diff % k != 0) return -1;
            if (diff > 0) pos += diff / k;
            else if (diff < 0) neg += (-diff) / k;
        }
        return pos == neg ? pos : -1;
    }
}

var minOperations = function(nums1, nums2, k) {
    if (k === 0) {
        for (let i = 0; i < nums1.length; i++) if (nums1[i] !== nums2[i]) return -1;
        return 0;
    }
    let pos = 0n, neg = 0n;
    const bk = BigInt(k);
    for (let i = 0; i < nums1.length; i++) {
        const diff = BigInt(nums1[i]) - BigInt(nums2[i]);
        if (diff % bk !== 0n) return -1;
        if (diff > 0n) pos += diff / bk;
        else if (diff < 0n) neg += (-diff) / bk;
    }
    return pos === neg ? Number(pos) : -1;
};
